const http=require('http'),fs=require('fs'),path=require('path');
const root=path.resolve(process.env.QA_FIXTURES||'outputs/求职工作台独立验收/fixtures');
const log=path.resolve(process.env.QA_RECEIVER_LOG||'work/receiver.ndjson');fs.mkdirSync(path.dirname(log),{recursive:true});
const types={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.json':'application/json; charset=utf-8'};
const server=http.createServer((req,res)=>{const u=new URL(req.url,'http://127.0.0.1');let f=path.resolve(root,'.'+(u.pathname==='/'?'/index.html':decodeURIComponent(u.pathname)));if(!f.startsWith(root+path.sep)){res.writeHead(403);return res.end()};try{res.setHeader('Content-Type',types[path.extname(f)]||'application/octet-stream');res.setHeader('Cache-Control','no-store');res.end(fs.readFileSync(f));}catch{res.writeHead(404);res.end('Not found')}}).listen(47941,'127.0.0.1',()=>console.log('Independent QA fixtures http://127.0.0.1:47941'));
const receiver=http.createServer((req,res)=>{res.setHeader('Access-Control-Allow-Origin','http://127.0.0.1:47941');res.setHeader('Access-Control-Allow-Headers','Content-Type');if(req.method==='OPTIONS'){res.end();return}let body='';req.on('data',c=>body+=c);req.on('end',()=>{fs.appendFileSync(log,JSON.stringify({at:new Date().toISOString(),url:req.url,method:req.method,body})+'\n');res.end('ok')})}).listen(47943,'127.0.0.1');
